import{_ as t,a,o as i,a6 as n}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse('{"title":"Email Templates","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-api/admin/marketing/communications/templates/index.md","filePath":"api/rest-api/admin/marketing/communications/templates/index.md","lastUpdated":1787725411000}'),o={name:"api/rest-api/admin/marketing/communications/templates/index.md"};function r(m,e,s,d,l,p){return i(),a("div",null,e[0]||(e[0]=[n('<h1 id="email-templates" tabindex="-1">Email Templates <a class="header-anchor" href="#email-templates" aria-label="Permalink to &quot;Email Templates&quot;">​</a></h1><p>An <strong>email template</strong> is a reusable HTML email body that a campaign sends to a customer group. It mirrors the admin <strong>Marketing → Communications → Email Templates</strong> screen.</p><h2 id="how-an-email-template-works" tabindex="-1">How an email template works <a class="header-anchor" href="#how-an-email-template-works" aria-label="Permalink to &quot;How an email template works&quot;">​</a></h2><p>A template is intentionally simple — a name, a status, and an HTML body.</p><ul><li><strong><code>name</code></strong> — a human-readable label used to pick the template when building a campaign.</li><li><strong><code>status</code></strong> — <code>active</code>, <code>inactive</code>, or <code>draft</code>. A draft or inactive template is kept for later but is not meant to be sent.</li><li><strong><code>content</code></strong> — the raw HTML email body. This is the markup delivered to recipients.</li></ul><p><strong>How templates are used.</strong> A campaign references a template plus a customer group; when the campaign sends, the template&#39;s HTML is delivered to every subscribed member of that group. The template itself holds no recipient or schedule information — that lives on the campaign.</p><p><strong>No mass delete.</strong> Templates are removed one at a time; the admin screen offers no bulk-delete action, so the API exposes none either.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/marketing/communications/templates-list.html">List</a></td><td><code>GET /api/admin/marketing/templates</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/templates-detail.html">Detail</a></td><td><code>GET /api/admin/marketing/templates/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/templates-create.html">Create</a></td><td><code>POST /api/admin/marketing/templates</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/templates-update.html">Update</a></td><td><code>PUT /api/admin/marketing/templates/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/communications/templates-delete.html">Delete</a></td><td><code>DELETE /api/admin/marketing/templates/{id}</code></td></tr></tbody></table>',9)]))}const u=t(o,[["render",r]]);export{h as __pageData,u as default};
